-- ============================================================
-- IMPOR ULANG JADWAL MENGAJAR (PRESISI, pakai ID langsung)
-- Semester Ganjil 2026/2027 — UPTD SMP NEGERI 9 BANJAR
-- ============================================================

-- Langkah 1: Hapus SEMUA jadwal lama (yang mungkin ada salah pasang guru)
delete from teaching_schedule;

-- Langkah 2: Impor ulang dengan pemetaan ID yang presis (bukan tebak nama)
on conflict (id) do nothing;

-- Langkah 3: Verifikasi total baris (harus 369 -- 375 dikurangi jadwal Dede Ati Sumiati
-- yang belum terdaftar sebagai guru, dan Yayat Hidayat sebagai Kepala Sekolah tidak mengajar)
select count(*) as total_setelah_impor_ulang from teaching_schedule;
